using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using V15Voice;
public static class TextTargetTests {
 static int count;static string folder;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}static void Reject(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name);}
 sealed class Engine:KokoroEngine {public int Calls,FailAt;public bool BadModel;public double Seconds=3;public override void CheckFiles(){if(BadModel)throw new Exception("fixture missing model");}public override Wave Generate(string text,double speed,string output){Calls++;if(Calls==FailAt)throw new Exception("fixture TTS error");int n=(int)Math.Round(Seconds/speed*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,n).Select(i=>i<n-1200?(short)(6000*Math.Cos(i*.063)):(short)0).ToArray()};}}
 static List<Cue> Script(){return LongText.Parse("This first sentence ends here. This second sentence finishes the script.");}
 static Engine New(){return new Engine{Root=folder,VoiceName="target test",DeviceMode="cpu"};}
 static RenderOptions Opt(List<Cue> cues,string name,double target=6.3){string source=Path.Combine(folder,name+".txt");if(!File.Exists(source))File.WriteAllText(source,String.Join(" ",cues.Select(c=>c.Text)),Encoding.UTF8);return new RenderOptions{Prose=true,Locked=false,BaseSpeed=1,MinSpeed=.8,MaxSpeed=1.3,TargetSeconds=target,TargetRaw=target.ToString(System.Globalization.CultureInfo.InvariantCulture),TargetChange=.10,Gap=.1,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=VoiceRenderReport.Snapshot(cues)}};}
 static string Run(List<Cue> c,Engine e,RenderOptions o,string name,Action<int,string> progress=null){return Renderer.Render(c,e,o,Path.Combine(folder,name+".wav"),progress??((p,m)=>{}));}
 static bool Fails(List<Cue> c,Engine e,RenderOptions o,string name){try{Run(c,e,o,name);return false;}catch{return true;}}
 public static int Main(){try{folder=Path.Combine(Path.GetTempPath(),"V15 TXT target "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
  Check(TextTargetVoice.Parse("45")==45&&TextTargetVoice.Parse("45s")==45&&TextTargetVoice.Parse("45 giây")==45,"Parse seconds with optional unit");Check(TextTargetVoice.Parse("01:30")==90&&TextTargetVoice.Parse("01:02:03")==3723&&TextTargetVoice.Parse("45,125")==45.125,"Parse mm:ss, hh:mm:ss and fractional seconds");Check(TextTargetVoice.Parse("",true)==0,"Blank queue target means natural TXT");foreach(string v in new[]{"","0","-1","NaN","00:60","00:60:00","06:00:01","45.0001"})Reject(()=>TextTargetVoice.Parse(v),"Reject invalid target "+v);
  var c=Script();var o=Opt(c,"success");o.NormalizeLoudness=true;var e=New();string hash=StateFiles.Hash(o.ReportContext.SourcePath);var progressValues=new List<ReadingProgress>();o.ReadingChanged=p=>progressValues.Add(p);string wav=Run(c,e,o,"success");var r=o.TargetResult;var report=o.RunReport;string text=File.ReadAllText(report.PathName);
  Check(r.Complete&&r.Fitted&&File.Exists(wav)&&FinalAudio.PcmFrames(wav)==151200,"Successful normalized WAV has exact requested PCM duration");Check(e.Calls==2&&r.Natural.HasValue&&r.Required.HasValue&&r.Attempts.Count>0,"Synthesize each sentence once then fit measured audio");Check(r.Speed>=.9&&r.Speed<=1.1&&Math.Abs(r.Adjustment)<=.0200001,"Default whole-TXT fit remains within ten percent and tiny tail correction");Check(hash==StateFiles.Hash(o.ReportContext.SourcePath),"TXT source bytes stay unchanged");Check(report.Units.All(u=>u.Before.HasValue&&u.After==null&&u.Start==null&&u.End==null&&u.OriginalStart.HasValue),"Whole-file fit never fabricates final per-sentence times");Check(text.Contains("TXT · CĂN THỜI LƯỢNG ĐÍCH")&&text.Contains("6.300s")&&text.Contains("TRƯỚC căn TXT đích")&&report.Wav==wav,"Detailed report includes target, measurements, trials and actual final path");Check(progressValues.Last().Final&&progressValues.Last().AudioSeconds==6.3&&progressValues.Take(progressValues.Count-1).All(p=>!p.Final),"Natural prepass never claims final target output completed");
  c=Script();o=Opt(c,"too-long",3);e=New();Check(Fails(c,e,o,"too-long")&&o.RunReport.FailureCode=="TIMELINE_MISMATCH"&&o.TargetResult.Measured>3&&!File.Exists(Path.Combine(folder,"too-long.wav")),"Too-long script fails with measured overflow and no final WAV");Check(o.TargetResult.Required>o.TargetResult.Maximum&&File.ReadAllText(o.RunReport.PathName).Contains("Dư "),"Overflow retains unconstrained required speed and prompt-edit direction");
  c=Script();o=Opt(c,"too-short",12);e=New();Check(Fails(c,e,o,"too-short")&&o.TargetResult.Measured<12&&!File.Exists(Path.Combine(folder,"too-short.wav"))&&o.TargetResult.Reason.Contains("Thiếu "),"Too-short script is reported instead of padding long silence");
  c=Script();o=Opt(c,"base-point-nine",6.5);o.BaseSpeed=.9;e=New();wav=Run(c,e,o,"base-point-nine");Check(Math.Abs(o.TargetResult.Required.Value-.9*o.TargetResult.Natural.Value/6.5)<1e-9&&o.TargetResult.Speed<=.99&&FinalAudio.PcmFrames(wav)==156000,"Speed estimate/fitting respects non-1.0 base speed");
  c=Script();o=Opt(c,"bounds");o.TargetChange=.25;o.GentleFit=true;Check(Math.Abs(TextTargetVoice.Minimum(o)-.9)<1e-9&&Math.Abs(TextTargetVoice.Maximum(o)-1.1)<1e-9,"Gentle-fit bounds intersect target cap");o.GentleFit=false;o.MinSpeed=.95;o.MaxSpeed=1.04;Check(TextTargetVoice.Minimum(o)==.95&&TextTargetVoice.Maximum(o)==1.04,"Explicit user speed bounds remain authoritative");
  c=Script();o=Opt(c,"cached-first");e=New();e.Archive=new SpeechArchive(Path.Combine(folder,"cache"));Run(c,e,o,"cached-first");o=Opt(Script(),"cached-second",6.1);wav=Run(Script(),e,o,"cached-second");Check(e.Calls==2&&o.RunReport.Units.All(u=>u.CacheCalls==1)&&File.Exists(wav),"Changing target reuses cached natural voice instead of rerunning TTS");
  c=Script();o=Opt(c,"model-error");e=New();e.BadModel=true;Check(Fails(c,e,o,"model-error")&&o.RunReport.FailureCode=="MODEL_PREFLIGHT_FAILED"&&o.TargetResult.Natural==null,"Missing model remains a model error with requested target recorded");c=Script();o=Opt(c,"tts-error");e=New();e.FailAt=2;Check(Fails(c,e,o,"tts-error")&&o.RunReport.FailureCode=="TTS_FAILED"&&o.TargetResult.Natural==null,"TTS failure is not misclassified as target overflow");
  c=Script();o=Opt(c,"cancel");e=New();bool stopped=false;try{Run(c,e,o,"cancel",(p,m)=>{if(p>=72)e.Cancelled=true;});}catch(OperationCanceledException){stopped=true;}Check(stopped&&o.RunReport.Outcome=="ĐÃ DỪNG"&&!File.Exists(Path.Combine(folder,"cancel.wav")),"Cancel during whole-TXT fit does not publish partial output");
  c=Script();o=Opt(c,"invalid-mode");o.Prose=false;o.Locked=true;e=New();Check(Fails(c,e,o,"invalid-mode")&&e.Calls==0&&o.RunReport.FailureCode=="INPUT_OR_SETUP_FAILED","Target option cannot silently alter SRT mode");c=Script();o=Opt(c,"nan-target",Double.NaN);e=New();Check(Fails(c,e,o,"nan-target")&&e.Calls==0,"Invalid target fails before synthesis");
  c=Script();o=Opt(c,"collision");e=New();string first=Run(c,e,o,"collision"),firstHash=StateFiles.Hash(first),firstReport=o.RunReport.PathName;Run(Script(),New(),Opt(Script(),"collision"),"collision");Check(StateFiles.Hash(first)==firstHash&&o.RunReport.PathName==firstReport&&Directory.GetFiles(folder,"collision*.wav").Length==2,"Repeated run preserves old WAV and report");
  Check(!Directory.GetDirectories(folder,".v15_txt_target_*").Any(),"Target intermediate folders are cleaned after success, failure and cancellation");
  var paths=new[]{"batch-fail","batch-target","batch-natural","batch-srt"}.Select(n=>Path.Combine(folder,n+(n=="batch-srt"?".srt":".txt"))).ToArray();for(int i=0;i<3;i++)File.WriteAllText(paths[i],"This first sentence ends here. This second sentence finishes the script.");File.WriteAllText(paths[3],"1\n00:00:00,000 --> 00:00:04,000\nA short source sentence.\n");var jobs=paths.Select(BatchJob.Load).ToList();jobs[0].TargetSeconds=1;jobs[1].TargetSeconds=6.3;e=New();BatchRunner.Run(jobs,false,()=>false,(job,output,notify)=>{var opt=Opt(job.Cues,Path.GetFileNameWithoutExtension(job.InputPath),job.TargetSeconds);AnchoredVoice.ConfigureBatch(opt,job.Timed,0,0);opt.TargetSeconds=job.Timed?0:job.TargetSeconds;return Renderer.Render(job.Cues,e,opt,output,notify);},(p,m)=>{});Check(jobs[0].State==JobState.Failed&&jobs.Skip(1).All(j=>j.State==JobState.Done),"Mixed queue continues after target failure and preserves natural/SRT modes");Check(FinalAudio.PcmFrames(jobs[1].OutputPath)==151200&&FinalAudio.PcmFrames(jobs[3].OutputPath)==96000,"Per-file queue target does not leak into SRT duration");
  string queue=Path.Combine(folder,"queue.xml");QueueStore.Save(queue,jobs);var restored=QueueStore.Load(queue);Check(restored[0].TargetSeconds==1&&restored[1].TargetSeconds==6.3&&restored[2].TargetSeconds==0&&restored[3].TargetSeconds==0,"Queue targets persist independently across reload");
  File.AppendAllText(paths[1]," A newly edited sentence follows.");restored=QueueStore.Load(queue);Check(restored[1].TargetSeconds==6.3&&restored[1].State==JobState.Queued,"Editing source content retains its requested target while invalidating old completion");
  var settings=VoiceSettings.From(new VoiceSettings{TextTargetChange=.15}.Xml());Check(settings.TextTargetChange==.15&&VoiceSettings.From(new System.Xml.Linq.XElement("settings")).TextTargetChange==.10,"Target speed cap persists with safe default for old settings");
  Console.WriteLine("TOTAL TXT TARGET "+count+" passed. Fixtures: "+folder);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
